using System;
using System.Collections.Generic;
using System.Linq;
namespace FootballDynasty {
 public sealed class Career {
  public readonly Database Data;public readonly Dictionary<string,Player> Players;public readonly Dictionary<string,Club> Clubs;
  public readonly Dictionary<string,SavedTeam> Teams=new Dictionary<string,SavedTeam>();
  public readonly List<MatchResult> Results=new List<MatchResult>();public readonly List<Tournament> Tournaments=new List<Tournament>();
  public readonly Dictionary<string,TacticalRole> Roles=new Dictionary<string,TacticalRole>();
  public TacticalRole GetRole(string id){if(Roles.TryGetValue(id,out var role))return role;var p=Players[id];if(p.position=="POR")return TacticalRole.Portero;if(p.position=="DEF")return TacticalRole.CentralDeCobertura;var peers=Team(p.club).lineup.Where(q=>Players[q].position==p.position).ToArray();int index=Array.IndexOf(peers,id);if(p.position=="MED")return index==0?TacticalRole.MediocentroDefensivo:TacticalRole.CreadorDeJuego;return peers.Length>=3&&(index==0||index==peers.Length-1)?TacticalRole.ExtremoInvertido:TacticalRole.CazadorDeAreas;}
  public bool SetRole(string club,string id,TacticalRole role){if(!Players.TryGetValue(id,out var p)||p.club!=club||!Enum.IsDefined(typeof(TacticalRole),role)||(p.position=="POR")!=(role==TacticalRole.Portero))return false;Roles[id]=role;return true;}
  public CoachProfile Coach;public string ManagedClub;
  public void AssignCoach(CoachProfile profile,string club){if(profile==null)throw new ArgumentException("Falta el entrenador.");var error=profile.Validate(Season);if(error!=null)throw new ArgumentException(error);if(!Data.leagues.Any(l=>l.clubs.Contains(club)))throw new ArgumentException("Elige un club de las seis ligas.");Coach=profile.CleanCopy();ManagedClub=club;}
  public MatchDifficulty Difficulty=MatchDifficulty.Medio;public int Season=2026,Round;private int randomSeed=27027;
  public bool SeasonFinished=>Round>=40;
  public void StartNextSeason(){if(!SeasonFinished)throw new InvalidOperationException("Termina la temporada antes de iniciar la siguiente.");Season++;Round=0;Results.Clear();SetupTournaments();}
  public static readonly Dictionary<string,string[]> Formations=new[]{"4-3-3","4-4-2","4-3-1-2","4-1-2-1-2","4-2-2-2","4-4-1-1","4-1-3-2","4-5-1","5-3-2","5-2-3","5-4-1","3-5-2","3-4-3"}.ToDictionary(f=>f,FormationLayout.Positions);
  public Career(Database data){Data=data;Players=data.players.ToDictionary(p=>p.id);Clubs=data.clubs.ToDictionary(c=>c.id);SetupTournaments();}
  public Player[] Squad(string club)=>Data.players.Where(p=>p.club==club).OrderByDescending(p=>p.rating).ToArray();
  public SavedTeam Team(string club){if(!Teams.TryGetValue(club,out var t)){t=new SavedTeam{club=club,formation="4-3-3"};Teams[club]=t;}if(!Valid(club,t.lineup,t.formation))t.lineup=Auto(club,t.formation);return t;}
  public string[] Auto(string club,string formation){var squad=Squad(club);var ids=new List<string>();foreach(var group in Formations[formation].GroupBy(p=>p))ids.AddRange(squad.Where(p=>p.position==group.Key).Take(group.Count()).Select(p=>p.id));return ids.ToArray();}
  public bool Valid(string club,string[] ids,string formation){if(ids==null||ids.Length!=11||ids.Distinct().Count()!=11||!Formations.ContainsKey(formation))return false;return ids.All(id=>Players.ContainsKey(id)&&Players[id].club==club)&&Formations[formation].GroupBy(p=>p).All(g=>ids.Count(id=>Players[id].position==g.Key)==g.Count());}
  public bool SetFormation(string club,string formation){if(!Formations.ContainsKey(formation))return false;var ids=Auto(club,formation);if(!Valid(club,ids,formation))return false;Teams[club]=new SavedTeam{club=club,formation=formation,lineup=ids};return true;}
  public bool SetSlot(string club,int slot,string id){var t=Team(club);if(slot<0||slot>=t.lineup.Length||!Players.ContainsKey(id)||Players[id].club!=club||Players[id].position!=Players[t.lineup[slot]].position)return false;var copy=(string[])t.lineup.Clone();int other=Array.IndexOf(copy,id);if(other>=0)copy[other]=copy[slot];copy[slot]=id;if(!Valid(club,copy,t.formation))return false;t.lineup=copy;return true;}
  public TransferResult Buy(string id,string buyer,string expectedSeller){
   if(!Players.TryGetValue(id,out var p)||!Clubs.ContainsKey(buyer)||!Clubs.ContainsKey(expectedSeller))return new TransferResult(false,"Jugador o club inválido.");
   if(p.club!=expectedSeller||buyer==p.club)return new TransferResult(false,"Propietario incorrecto o jugador ya adquirido.");
   double total=p.value+p.wage*4;if(Clubs[buyer].budget<total)return new TransferResult(false,"Presupuesto insuficiente.");if(Squad(buyer).Length>=60)return new TransferResult(false,"Plantilla completa.");
   if(!Clubs[expectedSeller].historic&&Squad(expectedSeller).Count(q=>q.position==p.position)<=Formations[Team(expectedSeller).formation].Count(pos=>pos==p.position))return new TransferResult(false,"El club necesita cubrir esa posición.");
   Clubs[buyer].budget-=total;Clubs[expectedSeller].budget+=p.value;p.club=buyer;p.contract=3;Teams.Remove(expectedSeller);return new TransferResult(true,p.name+" fichado. Selecciónalo en tu once.");
  }
  public static List<List<string[]>> Schedule(IEnumerable<string> ids){var ring=ids.ToList();if(ring.Count%2!=0)ring.Add(null);var rounds=new List<List<string[]>>();for(int r=0;r<ring.Count-1;r++){var day=new List<string[]>();for(int i=0;i<ring.Count/2;i++){var a=ring[i];var b=ring[ring.Count-1-i];if(a!=null&&b!=null)day.Add(r%2==0?new[]{a,b}:new[]{b,a});}rounds.Add(day);var last=ring[ring.Count-1];ring.RemoveAt(ring.Count-1);ring.Insert(1,last);}return rounds.Concat(rounds.Select(day=>day.Select(p=>new[]{p[1],p[0]}).ToList()).ToList()).ToList();}
  public sealed class Standing {public string Club;public int Played,Points,GF,GA;}
  public Standing[] Table(string[] ids,IEnumerable<MatchResult> matches){var rows=ids.ToDictionary(id=>id,id=>new Standing{Club=id});foreach(var m in matches){if(!rows.ContainsKey(m.home)||!rows.ContainsKey(m.away))continue;var a=rows[m.home];var b=rows[m.away];a.Played++;b.Played++;a.GF+=m.hg;a.GA+=m.ag;b.GF+=m.ag;b.GA+=m.hg;if(m.hg>m.ag)a.Points+=3;else if(m.ag>m.hg)b.Points+=3;else{a.Points++;b.Points++;}}return rows.Values.OrderByDescending(r=>r.Points).ThenByDescending(r=>r.GF-r.GA).ThenByDescending(r=>r.GF).ThenBy(r=>r.Club,StringComparer.Ordinal).ToArray();}
  private double Next(){randomSeed=unchecked(randomSeed*1664525+1013904223);return (uint)randomSeed/(double)uint.MaxValue;}
  private int Goals(double mean){double p=1,limit=Math.Exp(-mean);int n=0;do{p*=Next();n++;}while(p>limit&&n<12);return n-1;}
  public MatchResult Simulate(string a,string b,string competition){double diff=(Team(a).lineup.Select(id=>Players[id].rating).DefaultIfEmpty(65).Average()-Team(b).lineup.Select(id=>Players[id].rating).DefaultIfEmpty(65).Average())/20;return new MatchResult{home=a,away=b,hg=Goals(Math.Max(.25,1.5+diff)),ag=Goals(Math.Max(.25,1.1-diff)),competition=competition,round=Round};}
  public IEnumerable<string[]> NextLeague(string league)=>Round<Schedule(Data.leagues.First(l=>l.id==league).clubs).Count?Schedule(Data.leagues.First(l=>l.id==league).clubs)[Round]:new List<string[]>();
  public void Advance(MatchResult played=null){if(Round>=40)throw new InvalidOperationException("Temporada finalizada.");if(played!=null){var league=Data.leagues.FirstOrDefault(l=>NextLeague(l.id).Any(p=>p[0]==played.home&&p[1]==played.away));if(league==null||played.hg<0||played.ag<0||played.hg>99||played.ag>99)throw new InvalidOperationException("Resultado ajeno a la jornada.");played.competition=league.id;played.round=Round;}
   foreach(var league in Data.leagues)foreach(var pair in NextLeague(league.id))Results.Add(played!=null&&pair[0]==played.home&&pair[1]==played.away?played:Simulate(pair[0],pair[1],league.id));
   AdvanceTournaments();Round++;
  }
  private void SetupTournaments(){Tournaments.Clear();foreach(var l in Data.leagues.Where(l=>l.id!="mexico"))Tournaments.Add(new Tournament{id="cup-"+l.id,name=l.id=="spain"?"Copa del Rey":l.id=="england"?"FA Cup":"Copa · "+l.name,participants=l.clubs.ToArray(),alive=l.clubs.ToArray(),stage="Primera ronda"});Tournaments.Add(new Tournament{id="champions",name="Champions League",participants=Data.champions.ToArray(),alive=Data.champions.ToArray(),stage="Fase de liga"});var europa=Data.leagues.Where(l=>l.id!="mexico").SelectMany(l=>l.clubs).Where(id=>!Data.champions.Contains(id)).OrderByDescending(id=>Squad(id).Take(11).Average(p=>p.rating)).ThenBy(id=>id,System.StringComparer.Ordinal).Take(36).ToArray();Tournaments.Add(new Tournament{id="europa",name="Europa League",participants=europa,alive=europa.ToArray(),stage="Fase de liga"});foreach(var half in new[]{"apertura","clausura"})Tournaments.Add(new Tournament{id="mx-"+half,name="Liga MX · "+half,alive=Array.Empty<string>(),stage="Esperando clasificación"});}
  private void Knockout(Tournament t){var current=t.alive.ToList();if(current.Count<2)return;int power=1;while(power*2<current.Count)power*=2;int play=current.Count==power*2?current.Count:(current.Count-power)*2;var next=new List<string>();for(int i=0;i<play;i+=2){var m=Simulate(current[i],current[i+1],t.id);m.penalties=m.hg==m.ag;m.winner=m.hg>m.ag?m.home:m.ag>m.hg?m.away:Next()<.5?m.home:m.away;t.games.Add(m);next.Add(m.winner);}next.AddRange(current.Skip(play));t.alive=next.ToArray();t.stage="Quedan "+next.Count;if(next.Count==1){t.champion=next[0];t.stage="Finalizada";}}
  public static List<List<string[]>> EuropeanSchedule(string[] ids){var rounds=Schedule(ids).Take(8).ToList();var graph=ids.ToDictionary(id=>id,id=>new List<string>());var oriented=new Dictionary<string,string[]>();Func<string,string,string> key=(a,b)=>String.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;foreach(var day in rounds)foreach(var p in day){graph[p[0]].Add(p[1]);graph[p[1]].Add(p[0]);}foreach(var start in ids){var stack=new Stack<string>();stack.Push(start);while(stack.Count>0){var a=stack.Peek();if(graph[a].Count==0)stack.Pop();else{var b=graph[a][graph[a].Count-1];graph[a].Remove(b);graph[b].Remove(a);oriented[key(a,b)]=new[]{a,b};stack.Push(b);}}}return rounds.Select(day=>day.Select(p=>oriented[key(p[0],p[1])]).ToList()).ToList();}
  private void Europe(Tournament t){if(t.phase<8){foreach(var p in EuropeanSchedule(t.participants)[t.phase])t.games.Add(Simulate(p[0],p[1],t.id));t.phase++;t.stage="Fase de liga "+t.phase+"/8";if(t.phase==8){var rows=Table(t.participants,t.games);t.direct=rows.Take(8).Select(r=>r.Club).ToArray();t.alive=rows.Skip(8).Take(16).Select(r=>r.Club).ToArray();t.stage="Play-off";}return;}if(t.alive.Length==2){Knockout(t);return;}if(t.leg==0){t.ties.Clear();for(int i=0;i<t.alive.Length/2;i++){string a=t.alive[i],b=t.alive[t.alive.Length-1-i];var m=Simulate(b,a,t.id);t.games.Add(m);t.ties.Add(new Tie{a=a,b=b,ga=m.ag,gb=m.hg});}t.leg=1;t.stage="Eliminatoria vuelta";}else{var next=new List<string>();foreach(var tie in t.ties){var m=Simulate(tie.a,tie.b,t.id);int a=tie.ga+m.hg,b=tie.gb+m.ag;m.penalties=a==b;m.winner=a>b?tie.a:b>a?tie.b:Next()<.5?tie.a:tie.b;t.games.Add(m);next.Add(m.winner);}if(t.direct!=null&&t.direct.Length>0){t.alive=t.direct.Concat(next).ToArray();t.direct=Array.Empty<string>();}else t.alive=next.ToArray();t.leg=0;t.stage="Quedan "+t.alive.Length;}}
  private void AdvanceTournaments(){foreach(var t in Tournaments){if(!string.IsNullOrEmpty(t.champion))continue;if((t.id=="champions"||t.id=="europa")&&Round%2==1)Europe(t);else if(t.id.StartsWith("cup-")&&new[]{3,9,15,23,31}.Contains(Round))Knockout(t);else if(t.id.StartsWith("mx-")){int start=t.id=="mx-apertura"?16:33;if(Round==start){var league=Data.leagues.First(l=>l.id=="mexico");t.alive=Table(league.clubs,Results.Where(m=>m.competition=="mexico"&&(start==16?m.round<17:m.round>=17))).Take(8).Select(r=>r.Club).ToArray();}if(Round>=start&&Round<=start+2)Knockout(t);}}}
  public CareerSave Snapshot()=>new CareerSave{difficulty=Difficulty,roles=Roles.Select(r=>new SavedRole{player=r.Key,role=r.Value}).ToArray(),coach=Coach?.Copy(),managedClub=ManagedClub,season=Season,round=Round,rng=randomSeed,teams=Teams.Values.Select(t=>new SavedTeam{club=t.club,formation=t.formation,lineup=t.lineup.ToArray()}).ToArray(),owners=Players.Values.Select(p=>new SavedOwner{player=p.id,club=p.club}).ToArray(),budgets=Clubs.Values.Select(c=>new SavedBudget{club=c.id,budget=c.budget}).ToArray(),results=Results.ToArray(),tournaments=Tournaments.ToArray()};
  public void Restore(CareerSave save){
   if(save==null||save.version!=1||save.season<2026||save.round<0||save.round>40||save.owners==null||save.budgets==null||save.teams==null||save.results==null||save.tournaments==null)throw new ArgumentException("Guardado incompatible.");
   if(!Enum.IsDefined(typeof(MatchDifficulty),save.difficulty))throw new ArgumentException("Dificultad inválida.");
   if(save.coach!=null&&(save.coach.Validate(save.season)!=null||!Data.leagues.Any(l=>l.clubs.Contains(save.managedClub))))throw new ArgumentException("Perfil de entrenador inválido.");
   if(save.roles!=null&&(save.roles.Any(r=>r==null||r.player==null||!Players.ContainsKey(r.player)||!Enum.IsDefined(typeof(TacticalRole),r.role)||(Players[r.player].position=="POR")!=(r.role==TacticalRole.Portero))||save.roles.Select(r=>r.player).Distinct().Count()!=save.roles.Length))throw new ArgumentException("Roles tácticos inválidos.");
   // Validate the complete snapshot before touching the active career.
   if(save.owners.Length!=Players.Count||save.owners.Any(o=>o==null||o.player==null||o.club==null||!Players.ContainsKey(o.player)||!Clubs.ContainsKey(o.club))||save.owners.Select(o=>o.player).Distinct().Count()!=Players.Count)throw new ArgumentException("Propiedad inválida.");
   if(save.budgets.Length!=Clubs.Count||save.budgets.Any(b=>b==null||b.club==null||!Clubs.ContainsKey(b.club)||b.budget<0||double.IsNaN(b.budget)||double.IsInfinity(b.budget))||save.budgets.Select(b=>b.club).Distinct().Count()!=Clubs.Count)throw new ArgumentException("Fondos inválidos.");
   var owners=save.owners.ToDictionary(o=>o.player,o=>o.club);
   if(save.teams.Any(t=>t==null||t.club==null||!Clubs.ContainsKey(t.club)||t.formation==null||!Formations.ContainsKey(t.formation)||t.lineup==null||t.lineup.Length!=11||t.lineup.Distinct().Count()!=11||t.lineup.Any(id=>id==null||!Players.ContainsKey(id)||owners[id]!=t.club)||!Formations[t.formation].GroupBy(pos=>pos).All(g=>t.lineup.Count(id=>Players[id].position==g.Key)==g.Count()))||save.teams.Select(t=>t.club).Distinct().Count()!=save.teams.Length)throw new ArgumentException("Once inválido.");
   Func<MatchResult,bool> validMatch=m=>m!=null&&m.home!=null&&m.away!=null&&Clubs.ContainsKey(m.home)&&Clubs.ContainsKey(m.away)&&m.home!=m.away&&m.hg>=0&&m.hg<=99&&m.ag>=0&&m.ag<=99&&m.round>=0&&m.round<save.round;
   if(save.results.Any(m=>!validMatch(m)||!Data.leagues.Any(l=>l.id==m.competition&&l.clubs.Contains(m.home)&&l.clubs.Contains(m.away)))||save.results.GroupBy(m=>m.competition+"/"+m.round+"/"+m.home+"/"+m.away).Any(g=>g.Count()>1))throw new ArgumentException("Resultados inválidos.");
   var restoredTournaments=save.tournaments;var oldIds=Tournaments.Where(t=>t.id!="europa").Select(t=>t.id).OrderBy(id=>id).ToArray();if(restoredTournaments.All(t=>t!=null)&&restoredTournaments.Select(t=>t.id).OrderBy(id=>id).SequenceEqual(oldIds))restoredTournaments=restoredTournaments.Concat(new[]{Tournaments.Single(t=>t.id=="europa")}).ToArray();
   var expected=Tournaments.Select(t=>t.id).OrderBy(id=>id).ToArray();
   if(restoredTournaments.Any(t=>t==null||t.id==null)||!restoredTournaments.Select(t=>t.id).OrderBy(id=>id).SequenceEqual(expected))throw new ArgumentException("Torneos inválidos.");
   foreach(var t in restoredTournaments){
    Func<string[],bool> validIds=ids=>ids==null||(ids.All(id=>id!=null&&Clubs.ContainsKey(id))&&ids.Distinct().Count()==ids.Length);
    if(!validIds(t.participants)||!validIds(t.alive)||!validIds(t.direct)||t.alive==null||t.games==null||t.ties==null||t.games.Any(m=>!validMatch(m)||m.competition!=t.id)||t.ties.Any(tie=>tie==null||tie.a==null||tie.b==null||!Clubs.ContainsKey(tie.a)||!Clubs.ContainsKey(tie.b)||tie.ga<0||tie.gb<0)||t.phase<0||t.phase>8||t.leg<0||t.leg>1||(!string.IsNullOrEmpty(t.champion)&&!Clubs.ContainsKey(t.champion)))throw new ArgumentException("Torneo inválido.");
   }
   foreach(var o in save.owners)Players[o.player].club=o.club;foreach(var b in save.budgets)Clubs[b.club].budget=b.budget;
   Teams.Clear();foreach(var t in save.teams)Teams[t.club]=new SavedTeam{club=t.club,formation=t.formation,lineup=(string[])t.lineup.Clone()};
   Results.Clear();Results.AddRange(save.results);Tournaments.Clear();Tournaments.AddRange(restoredTournaments);Difficulty=save.difficulty;Roles.Clear();if(save.roles!=null)foreach(var role in save.roles)Roles[role.player]=role.role;Coach=save.coach?.CleanCopy();ManagedClub=save.coach==null?null:save.managedClub;Round=save.round;Season=save.season;randomSeed=save.rng;
  }
 }
}
